-- One membership per person per subsidiary (ISSUE-82, database review C1).
-- Better Auth's add-member checks for a row and then inserts without a
-- transaction, so concurrent adds could leave two rows for the same pair.
-- Custom migration because auth/.../schema.ts is regenerated by
-- `bun run auth:schema` and would lose a hand-added unique index.
--
-- Duplicates are removed first, keeping the earliest row. The delete trigger
-- is switched off for that step: it revokes every assignment and elevation in
-- the organization when a member row goes, and here the person stays a member.
-- The count is reported as a NOTICE in the migration output.
ALTER TABLE "auth"."member" DISABLE TRIGGER revoke_departed_subsidiary_access;--> statement-breakpoint
DO $$
DECLARE removed integer;
BEGIN
  WITH ranked AS (
    SELECT "id", row_number() OVER (
      PARTITION BY "organization_id", "user_id" ORDER BY "created_at", "id"
    ) AS position
    FROM "auth"."member"
  )
  DELETE FROM "auth"."member" WHERE "id" IN (SELECT "id" FROM ranked WHERE position > 1);
  GET DIAGNOSTICS removed = ROW_COUNT;
  RAISE NOTICE 'auth.member: removed % duplicate membership row(s)', removed;
END $$;--> statement-breakpoint
ALTER TABLE "auth"."member" ENABLE TRIGGER revoke_departed_subsidiary_access;--> statement-breakpoint
CREATE UNIQUE INDEX "member_organizationId_userId_uidx" ON "auth"."member" USING btree ("organization_id","user_id");
